#include "WorkflowTools.h"
#include "RecreationSearch.h"
#include <iostream>
#include <stdexcept>
void require(bool b,const char* s){if(!b)throw std::runtime_error(s);}
nova::Sound reference(){nova::Sound s;s.sampleRate=16000;s.left.resize(44800);s.right=s.left;for(size_t i=0;i<s.left.size();++i){double t=i/s.sampleRate;int n=static_cast<int>(t/1.4);double local=t-n*1.4,hz=440*std::pow(2.,((n?72:69)-69+.37)/12.),env=std::min(1.,local/.015)*std::clamp((1.22-local)/.06,0.,1.);s.left[i]=s.right[i]=static_cast<float>(env*.16*(std::sin(2*nova::pi*hz*local)+.2*std::sin(4*nova::pi*hz*local)));}nova::analyse(s);return s;}
int main(){try{auto p=nova::preset(764);p.fineTune=7;p.boost=2;p.presetTrim=12;auto locked=nova::varyPatch(p,2,{true,true,true,true},5);require(nova::toGenes(p)==nova::toGenes(locked),"all variation groups locked");for(unsigned seed=0;seed<128;++seed){auto v=nova::varyPatch(p,2,{},seed);require(v.engine==p.engine&&v.root==p.root&&v.transpose==p.transpose&&v.fineTune==7&&v.boost==2&&v.presetTrim==12&&v.master==p.master,"variation preserves pitch and gain");require(std::isfinite(v.cutoff)&&v.cutoff>=30&&v.cutoff<=20000&&v.attack>=.001f&&v.release<=8,"bounded variation");}auto d=nova::preset(20);nova::keepPresetLocks(d,p,true,true);require(d.master==p.master&&d.presetTrim==p.presetTrim&&d.reverb==p.reverb,"preset locks");require(nova::patchSimilarity(p,p)==0,"similarity identity");auto s=reference();std::atomic<bool> cancel{false};float last=0;auto result=nova::searchRecreation(s,2.5,160,true,true,0,cancel,[&](float f,int,double,int){require(std::isfinite(f)&&f>=0&&f<=1,"bounded progress");last=f;});require(result.fit.valid&&!result.fit.cancelled,"unknown instrument automatic recreation");require(result.review.analysis.uniqueNotes>=2,"multiple notes discovered");require(!result.alternatives.empty()&&result.alternatives.size()<=3&&last==1,"verified alternatives and completion");int engines=0;for(double loss:result.engineErrors)if(loss<999)++engines;require(engines>=4,"multiple engines compared");for(auto& c:result.alternatives)require(c.valid&&std::isfinite(c.error)&&c.parameters.fineTune==0&&c.parameters.tracking==0&&(!c.pitchMeasured||c.pitchErrorCents<=12),"centred alternatives pass pitch gate");cancel.store(true);auto stopped=nova::searchRecreation(s,0,160,true,true,0,cancel);require(stopped.fit.cancelled&&!stopped.fit.valid,"cancel does not publish");std::cout<<"PASS: "<<engines<<" engines, multiple notes, "<<result.alternatives.size()<<" alternatives; pitch, locks, cancellation\n";}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
